import os
from pathlib import Path
print('cwd', os.getcwd())
for root in ['/', '/app', '/workspace', '/home', '/tmp']:
    p=Path(root)
    try:
        print(root, [(x.name, 'd' if x.is_dir() else 'f') for x in p.iterdir()][:100])
    except Exception as e: print(root, type(e).__name__, str(e))

